class BytesIOCopy:
    """A binary stream that copies everything written to it to another
    stream, while itself being backed by a real OS-level file so that
    ``fileno()`` works (e.g. for use as ``stdout``/``stderr`` of
    :func:`subprocess.run`).

    .. versionadded:: 8.2

    .. versionchanged:: 8.3
        Backed by a real file instead of :class:`io.BytesIO` so that
        ``fileno()`` is supported.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def fileno(self) -> int:
        return self._file.fileno()

    def isatty(self) -> bool:
        return False

    def readable(self) -> bool:
        return True

    def writable(self) -> bool:
        return True

    def seekable(self) -> bool:
        return True

    def tell(self) -> int:
        return self._file.tell()

    def seek(self, *args: t.Any, **kwargs: t.Any) -> int:
        return self._file.seek(*args, **kwargs)

    def read(self, *args: t.Any, **kwargs: t.Any) -> bytes:
        return self._file.read(*args, **kwargs)

    def close(self) -> None:
        self._file.close()

